CREATE OR REPLACE FUNCTION public.actualizar_afinidad_desde_escucha()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  genre_value text;
  delta numeric := 0;
  session_delta integer := 0;
BEGIN
  SELECT lower(r.genero) INTO genre_value
  FROM public.reels r
  WHERE r.id = COALESCE(NEW.reel_id, OLD.reel_id);

  IF genre_value IS NULL OR genre_value = '' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    delta := public.playback_signal_score(
      NEW.listened_ms, NEW.completion_ratio, NEW.completed, NEW.skipped, NEW.replay_count
    );
    session_delta := 1;
  ELSIF TG_OP = 'UPDATE' THEN
    delta := public.playback_signal_score(
      NEW.listened_ms, NEW.completion_ratio, NEW.completed, NEW.skipped, NEW.replay_count
    ) - public.playback_signal_score(
      OLD.listened_ms, OLD.completion_ratio, OLD.completed, OLD.skipped, OLD.replay_count
    );
  ELSE
    delta := -public.playback_signal_score(
      OLD.listened_ms, OLD.completion_ratio, OLD.completed, OLD.skipped, OLD.replay_count
    );
    session_delta := -1;
  END IF;

  INSERT INTO public.user_genre_affinity (
    user_id, genre, behavioral_score, listening_sessions, last_interaction_at
  ) VALUES (
    COALESCE(NEW.user_id, OLD.user_id),
    genre_value,
    GREATEST(-50::numeric, LEAST(250::numeric, delta)),
    GREATEST(0, session_delta),
    timezone('utc'::text, now())
  )
  ON CONFLICT (user_id, genre) DO UPDATE
  SET behavioral_score = GREATEST(
        -50::numeric,
        LEAST(250::numeric, public.user_genre_affinity.behavioral_score + delta)
      ),
      listening_sessions = GREATEST(
        0,
        public.user_genre_affinity.listening_sessions + session_delta
      ),
      last_interaction_at = timezone('utc'::text, now());

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.broadcast_conversation_read_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF OLD.last_delivered_at IS DISTINCT FROM NEW.last_delivered_at THEN
    PERFORM realtime.send(
      jsonb_build_object(
        'user_id', NEW.user_id,
        'last_delivered_at', NEW.last_delivered_at
      ),
      'delivered',
      'conversation:' || NEW.conversation_id::text,
      true
    );
  END IF;

  IF OLD.last_read_at IS DISTINCT FROM NEW.last_read_at THEN
    PERFORM realtime.send(
      jsonb_build_object(
        'user_id', NEW.user_id,
        'last_read_at', NEW.last_read_at
      ),
      'read',
      'conversation:' || NEW.conversation_id::text,
      true
    );
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.broadcast_message_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  conversation_uuid uuid;
BEGIN
  conversation_uuid := COALESCE(NEW.conversation_id, OLD.conversation_id);
  PERFORM realtime.broadcast_changes(
    'conversation:' || conversation_uuid::text,
    TG_OP,
    TG_OP,
    TG_TABLE_NAME,
    TG_TABLE_SCHEMA,
    NEW,
    OLD
  );
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sincronizar_ubicacion_evento()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.latitud IS NULL OR NEW.longitud IS NULL THEN
    NEW.ubicacion_geog := NULL;
  ELSE
    NEW.ubicacion_geog := gis.ST_SetSRID(
      gis.ST_MakePoint(NEW.longitud, NEW.latitud),
      4326
    )::gis.geography;
  END IF;
  RETURN NEW;
END;
$function$
